-- 약품·병용금기·연령금기 시드 데이터 (반복 실행해도 안전: 이미 있으면 건너뛴다)
-- 출처: 식약처 의약품개요정보(e약은요) + 건강보험심사평가원 DUR 품목 리스트(2026.6)
-- * item_seq: e약은요 약품은 품목기준코드, 병용금기 상대 약품(DUR 전용)은 'DUR'+제품코드
-- * 연령금기: 개월·주 단위는 만 나이로 바꿨고 원문 기준을 내용 앞에 [ ] 로 남겼다. '이상' 기준은 제외했다.

INSERT INTO medicine(item_seq, product_name, company_name, efficacy, usage_text, precautions, storage) VALUES
('198701721', '나르펜정400밀리그램(이부프로펜)(수출명:PANALTab.)', '초당약품공업(주)', '이 약은 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 감기로 인한 발열 및 동통, 요통, 월경곤란증, 수술후 동통과 강직성 척추염, 두통, 치통, 근육통, 신경통, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에 성인은 1회 1/2정~1.5정(200~600 mg), 1일 3~4회 복용하며 1일 최고 3200 mg까지 복용할 수 있습니다. 

연소성 류마티양 관절염에는 1일 체중 kg당 30-40 mg을 3~4회 분할하여 복용하며, 경증 및 중등도의 동통이나 감기에는 성인 1회 1/2정~1정(200~400 mg), 1일 3~4회 복용합니다. 연령, 증상에 따라 적절히 증감할 수 있습니다.

11~14세는 1회 200~250 mg, 7~10세는 1회 150~200 mg, 3~6세는 1회 100~150 mg, 1~ 2세는 1회 50~100 mg을 1일 3~4회 경구투여합니다.

체중이 30 kg 미만인 어린이는 1일량이 500 mg을 초과해서는 안되며 공복시 복용은 피하는 것이 바람직합니다.

권장용량을 초과하여 복용하지 마십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.

이 약 복용 시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다. 이 약에 과민증 환자, 위장관궤양, 위장관 출혈 또는 경험자, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식 또는 경험자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 저해제 포함)에 천식, 두드러기, 알레르기 반응과 같은 과민증 또는 경험자, 관상동맥(심장동맥) 우회로술 전후 통증발생 환자, 임신 말기 3개월 기간에 해당하는 임부, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 혈액이상 또는 경험자, 출혈경향이 있는 환자, 간경화, 간장애 또는 경험자, 신장장애 또는 경험자, 심장기능부전 또는 심질환, 고혈압, 과민증 경험자, 전신성홍반성루푸스 및 혼합 결합조직질환 환자, 궤양성대장염, 크론병, 고령자 및 소아, 임부, 수유부, 황색4호(타르트라진)에 과민증 환자는 의사 또는 약사와 상의하십시오.

의사 또는 약사의 지시 없이 통증에 10일 이상(성인) 또는 5일 이상(소아) 복용하지 않고 발열에 3일 이상 복용하지 마십시오.', '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199501735', '넬슨이부프로펜정200밀리그램(이부프로펜)', '한국넬슨제약(주)', '이 약은 류마티양 관절염, 연소성 류마티양 관절염, 골관절염(퇴행성 관절질환), 감기로 인한 발열 및 동통, 요통, 월경곤란증, 수술후 동통과 강직성 척추염, 두통, 치통, 근육통, 신경통, 급성통풍, 건선성 관절염, 연조직손상(염좌, 좌상), 비관절 류마티스질환(건염, 건초염, 활액낭염)에 사용합니다.', '성인은 류마티양 관절염, 골관절염, 강직성 척추염, 연조직손상, 비관절 류마티스질환, 급성통풍, 건선성 관절염에는 1회 1~3정(200~600 mg) 1일 3~4회 1일 최고 16정(3,200 mg)까지 복용할 수 있으며, 연소성 류마티양 관절염에는 1일 체중 kg당 30~40 mg을 3~4회 분할 복용, 경증 및 중등도의 동통이나 감기에는 성인 1회 1~2정(200~400 mg) 1일 3~4회 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.

이 약 복용 시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다.

조절되지 않는 고혈압, 울혈심부전증, 확립된 허혈성 심장질환, 말초동맥질환, 뇌혈관질환을 가진 환자는 고용량 이부프로펜(1일 2,400 mg) 복용을 피해야 하며, 심혈관계 위험 요소(고혈압, 고지혈증, 당뇨병, 흡연 등)를 가지고 있는 환자는 고용량 이부프로펜(1일 2,400 mg) 복용이 필요한 경우 이 약을 복용하기 전에 의사 또는 약사와 상의하십시오. 이 약에 과민증 환자, 위장관궤양, 위장관출혈, 심한 혈액이상, 심한 간장애, 심한 신장장애, 심한 심장기능부전, 심한 고혈압, 기관지천식, 아스피린 또는 다른 소염진통제에 의한 천식, 두드러기, 알레르기 반응 경험 환자, 심장동맥 우회로술 전후 통증발생 환자, 임신 말기 3개월 기간의 임부, 수유부, 항암요법으로 고용량 메토트렉세이트를 투여 중인 환자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

권장용량을 초과하여 복용하지 마십시오.

이 약을 복용하기 전에 혈액이상, 출혈경향 환자, 간경화, 간장애, 신장장애, 심장기능부전, 심질환, 고혈압, 전신홍반루푸스, 혼합결합조직질환, 궤양성대장염, 크론병, 노인, 만 2세 미만의 소아, 임부, 수유부, 저용량 아스피린을 복용하는 사람, 수두인 경우 의사 또는 약사와 상의하십시오.

감기에 복용할 경우에는 원칙적으로 5일 이내로 복용하며 의사 또는 약사의 지시 없이 통증에 10일 이상(성인) 또는 5일 이상(소아) 복용하지 않고 발열에 3일 이상 복용하지 않습니다.', '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199300273', '멕시롱액(돔페리돈)', '동아제약(주)', '이 약은 오심, 구토 증상의 완화에 사용합니다.', '성인 및 청소년(12세 이상, 35 kg 이상)은 1회 10 mg(레보도파 투여시 5 mg)을 1일 3회 식전에 복용합니다.

1일 최대 복용량은 30 mg이며, 일반적으로 1주일을 초과하여 사용하지 않도록 합니다.', '이 약에 과민증 환자, 위운동 촉진이 위험한 환자(위장관출혈, 기계적폐쇄증, 천공), 프로락틴분비종양, 강력한 CYP3A4 저해제를 병용투여중인 환자, 중등도 및 중증의 간장애, 임부 또는 임신하고 있을 가능성이 있는 여성, QTc 간격을 지연시키는 약물을 병용투여중인 환자, 전해질 불균형(저칼륨혈증, 고칼륨혈증, 저마그네슘혈증)을 보이는 환자, 심부전과 같은 심장 기저질환 환자, 몸무게 35 kg 미만의 소아, (경구용 현탁액의 경우) 소르비톨 불내성 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 소아, 신장애 또는 경증 간장애 환자, 고령자, 심장질환 환자 또는 경험자, 수유부, 유방암 경험자, 카라멜 성분에 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.

이 약 복용 후 졸음 및 어지러움이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.', '빛을 피해 실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199601110', '크리맥액(돔페리돈)', '일양약품(주)', '이 약은 오심, 구토 증상의 완화에 사용합니다.', '성인 및 청소년(12세 이상, 35 kg 이상)은 1회 10 mg(레보도파 투여시 5 mg)을 1일 3회 식전에 복용합니다.1일 최대 복용량은 30 mg이며, 일반적으로 1주일을 초과하여 사용하지 않도록 합니다.', '이 약에 과민증 환자, 위운동 촉진이 위험한 환자(위장관출혈, 기계적폐쇄증, 천공), 프로락틴분비종양, 강력한 CYP3A4 저해제를 병용투여중인 환자, 중등도 및 중증의 간장애, 임부 또는 임신하고 있을 가능성이 있는 여성, QTc 간격을 지연시키는 약물을 병용투여중인 환자, 전해질 불균형(저칼륨혈증, 고칼륨혈증, 저마그네슘혈증)을 보이는 환자, 심부전과 같은 심장 기저질환 환자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 소아, 신장애 또는 경증 간장애 환자, 고령자, 심장질환 환자 또는 경험자, 수유부, 유방암 경험자, 카라멜 성분에 과민증 환자는 의사 또는 약사와 상의하십시오.이 약 복용 후 졸음 및 어지러움이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.', '빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('201309112', '경동아스피린장용정', '경동제약(주)', '이 약은 심근경색, 뇌경색, 불안정형 협심증에서 혈전 생성 억제와 관상동맥 우회술(CABG) 또는 경피경관 관상동맥 성형술(PTCA) 후 혈전 생성 억제와 고위험군환자(허혈성 심장질환의 가족력, 고혈압, 고콜레스테롤혈증, 비만, 당뇨 등 복합적 위험인자를 가진 환자)에서 심혈관계 위험성 감소에 사용합니다.', '성인은 1회 1정, 1일 1회 복용합니다.

이 약은 장용정이므로 충분한 물과 함께 식전에 복용할 수 있습니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다. 이 약 또는 다른 살리실산제제에 과민증 환자, 소화성궤양, 아스피린천식 또는 경험자, 혈우병, 심한 간장애, 심한 신장애, 심한 심기능부전, 출혈경향, 일주일 동안 메토트렉세이트 15밀리그람(15 mg/주) 이상의 용량을 병용 투여하는 환자, 임신 3기에 해당하는 임부는 복용하지 마십시오.

이 약을 복용하기 전에 신장애, 심혈관 순환 기능 이상(신혈관 질환, 울혈성 심부전, 체액감소, 큰 수술, 패혈증 또는 주요 출혈사고 등), 간장애 또는 경험자, 심기능 이상, 혈액 이상 또는 경험자, 기관지천식, 수술전의 환자, 3세 이하의 유아, 진통제, 소염제, 항류마티스제에 대한 과민증 및 다른 알레르기 질환 경험자, 고령자, 항응고제를 병용투여하는 환자, 포도당-6-인산염 탈수소효소(G6PD) 결핍 환자, 수두 또는 인플루엔자 환자는 의사 또는 약사와 상의하십시오.

