('202402092', '디펜콜콜드시럽', '동성제약(주)', '이 약은 콧물, 코막힘, 재채기, 인후(목구멍)통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통 등 감기의 제증상의 완화에 사용합니다.', '만 15세 이상 1회 1포(20 mL), 만 11세 이상∼만 15세 미만 1회 2/3포, 만 7세 이상∼만 11세 미만 1회 1/2포, 만 3세 이상~만 7세 미만 1회 1/3포, 만 2세 이상~만 3세 미만 1회 1/4포를 1일 3회 식후 30분에 복용합니다.

단, 필요한 경우에는 취침 시 복용하며 원칙적으로 복용간격은 4시간으로 하십시오.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.

