아세트아미노펜으로 일일 최대 용량(4,000 mg)을 초과하여 복용하지 마십시오. 간손상을 일으킬 수 있습니다. 아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오. 이 약에 과민증 및 경험자, 이 약 및 다른 해열진통제, 감기약 복용 시 천식 경험자, 만 2세 미만의 소아는 이 약을 복용하지 마십시오.

