('201902614', '마인트롤정(세인트존스워트80%메탄올건조엑스)', '동국제약(주)', '이 약은 불안, 무기력 상태, 가볍고 일시적인 우울증상의 완화에 사용합니다.', '성인 및 12세 이상의 소아는 1회 1정(세인트존스워트80%메탄올건조엑스 300 mg) 1일 3회 소량의 물과 함께 씹지 말고 복용합니다.', '이 약에 과민증 환자, 심한 우울증 환자, 피부 광과민반응 경험자, 임부 및 임신 가능성이 있는 여성 또는 수유부, 12세 미만의 어린이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하는 동안 강한 자외선 노출(장시간 일광욕, 태양광램프, 선탠침대)을 피하십시오.정해진 용법과 용량을 잘 지키십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200102561', '리치칼슘연질캡슐(알파칼시돌)', '신일제약(주)', '이 약은 만성신부전, 부갑상선기능저하증, 비타민 D 저항성 구루병·골연화증 질환의 비타민 D 대사이상에 수반되는 증상(저칼슘혈증, 테타니, 뼈의 통증, 뼈의 병변(변화) 등)의 개선과 골다공증에 사용합니다.', '성인은 만성신부전·골다공증에 1일 1회 1~2캡슐(0.5~1 ㎍)을 복용하며 부갑상선기능저하증, 기타 비타민 D 대사이상에 따른 질환에 1일 1회 2~8캡슐(1~4 ㎍)을 복용합니다.어린이는 골다공증에 1일 1회 체중 kg당 0.01~0.03 ㎍을 복용하며 기타질환에는 1일 1회 체중 kg당 0.05~0.1 ㎍을 복용합니다.', '이 약에 과민증 환자, 고칼슘혈증, 고인산혈증, 고마그네슘혈증, Ca×P 생성물 ＞ 3.7 (mmol/L)2 환자, 혈액 pH ＞ 7.44의 알칼리혈증(우유 알칼리 증후군, Burnett 증후군), 비타민 D 독성발현의 증후가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 어린이, 고령자, 신장결석 경험자, 유육종증 환자, 황색5호에 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.식이 또는 보급제로서 칼슘섭취에 대한 지시를 준수하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200005087', '아시돌연질캡슐1마이크로그램(알파칼시돌)', '한국프라임제약(주)', '이 약은 만성신부전, 부갑상선기능저하증, 비타민 D 저항성 구루병·골연화증 질환의 비타민 D 대사이상에 수반되는 증상(저칼슘혈증, 테타니, 뼈의 통증, 뼈의 병변(변화) 등)의 개선과 골다공증에 사용합니다.', '성인의 만성신부전·골다공증에 1일 1회 0.5～1 ㎍, 부갑상선기능저하증, 기타 비타민 D 대사이상에 따른 질환에 1일 1회 1～4 ㎍을 복용합니다.어린이의 골다공증에 1일 1회 체중 kg당 0.01～0.03 ㎍, 기타 질환에 1일 1회 체중 kg당 0.05～0.1 ㎍을 복용합니다.', '고칼슘혈증, 고인산혈증, 고마그네슘혈증, Ca×P 생성물 ＞ 3.7 (mmol/L)2 환자, 혈액 pH ＞ 7.44의 알칼리혈증, 비타민 D 독성발현의 증후가 있는 환자, 이 약에 과민증 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 임부 또는 임신하고 있을 가능성이 있는 여성, 어린이, 고령자, 신장결석 경험자, 유육종증(sarcoidosis) 환자, 수유부는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.식이 또는 보급제로서 칼슘섭취에 대한 지시를 준수하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200200157', '모드코프시럽', '(주)종근당', '이 약은 기침, 가래, 콧물, 코막힘, 재채기에 사용합니다.', '만 2세~6세는 1회 5 mL씩, 만 6세~12세는 1회 10 mL씩, 4~6시간마다 복용하고, 24시간 동안 4회 이상 복용하지 않습니다.', '이 약은 체내에서 페닐알라닌으로 대사되는 아스파탐이 함유되어 페닐알라닌의 섭취를 규제할 필요가 있는 페닐케톤뇨증 환자는 복용하지 마십시오.

급성전신발진고름물집증과 같은 중증 피부 이상반응이 나타나는 경우 복용을 중단하고 의사 또는 약사와 상의하십시오. 중증 또는 조절되지 않는 고혈압, 중증 급성 또는 만성 신장질환/신부전 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 만 2세 미만의 소아, 알레르기 체질, 약에 의한 알레르기 증상 경험자, 간장애, 신장애, 갑상샘질환, 당뇨병, 고열, 허약자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 심장애 및 고혈압, 과도한 가래가 동반되는 기침, 천식과 같은 지속 또는 만성 기침 환자는 의사 또는 약사와 상의하십시오.

정해진 용법과 용량을 잘 지키십시오.

어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.

