자세한 사항은 허가사항의 상세정보를 참고하십시오.', '혈전증과 같은 심각한 심혈관계 위험이 증가할 수 있어 경구피임제를 복용하는 여성은 흡연을 삼갑니다. 35세 이상 흡연자는 이 약을 복용하지 마십시오. 이 약에 과민증, 성호르몬 의존성 종양(예 : 자궁내막암), 유방암 환자나 의심자 및 경험자, 혈전성 동맥정맥염, 혈전색전증 환자 또는 경험자, 뇌혈관 또는 관상동맥질환(특히 심근경색), 진단하지 않은 비정상적인 생식기 출혈, 중등도 및 중증 고혈압, 중등도 및 중증 간장애, 두빈-존슨 증후군 및 로터증후군 환자, 황달, 담즙울체, 간염 및 양성 또는 악성 간종양 환자 또는 경험자, 겸상적혈구빈혈, 혈관변성을 수반하는 중증 당뇨병, 중증 고지혈증, 고지단백혈증 및 포르피린증 등의 중증대사장애, 임신중 지속적인 가려움, 임신포진, 임부 또는 임신하고 있을 가능성이 있는 부인 및 수유부, 뇌하수체 종양, 고프로락틴혈증, 심장판막증, 혈관병변을 수반한 당뇨병 환자, 췌장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자, 선천성 또는 후천성 과응고병증 환자, 35세 이상 흡연자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 흡연자, 고혈압 환자, 비만자, 40세 이상의 여성, 간질, 편두통 환자, 동맥질환의 가족력이 있거나 정맥류 경험자, 전신성 홍반성 루푸스, 유방암의 가족력이 있는 환자, 우울증 환자 및 경험자, 심·신부전, 비전형적 과다증식된 유선병증 환자, 유방결절 경험자, 심장판막질환, 동맥세동 환자 및 경험자, 고지혈증의 가족력이 있는 환자, 담낭질환 및 담석증 경험자, 자궁내막증, 천식 또는 기미, 말초혈액순환장애, 당뇨병, 전조를 수반하지 않는 편두통 환자는 의사 또는 약사와 상의하십시오.

이 약은 HIV감염(에이즈) 및 다른 성병의 예방 기능은 없습니다.

심한 위장관계 질환이 있는 경우, 흡수가 불완전할 수 있으므로 부가적인 피임법을 사용하십시오.

