자세한 사항은 허가사항 상세정보를 참고하십시오.', '흡연은 경구피임제로 인한 중증의 심혈관계 이상반응의 위험성을 증대시키며 이 위험성은 나이와 흡연량(1일 15개 이상)에 따라 증가되고, 특히 35세 이상의 여성에게 현저하게 나타나므로 경구피임제를 복용하는 여성은 흡연을 삼가십시오. 이 약에 과민증 환자, 에스트로겐 의존성 종양 환자 및 의심이 되는 환자 또는 경험자, 혈전성 동맥정맥염, 혈전색전증, 심정맥성혈전증 환자 또는 경험자, 및 혈전성 판막질환자, 혈전성 심박동이상, 선천성 또는 후천성 혈전성향증, 뇌혈관 또는 관상동맥 질환,정맥 또는 동맥 혈전증의 위험이 높은 환자, 진단하지 않은 비정상적인 생식기 출혈, 중등도 및 중증 고혈압, 간장애, 두빈-존슨 증후군 및 로터증후군, 황달, 담즙울체, 간염 및 양성 또는 악성 간종양 환자 또는 경험자, 겸상적혈구빈혈, 혈관변성을 수반하는 중증 당뇨병, 중증 고지혈증, 고지단백혈증 및 포르피린증 등의 중증 대사장애, 임신중 지속적인 가려움, 임신포진, 유천포창 또는 이경화증 경험자, 임부 또는 임신하고 있을 가능성이 있는 부인 및 수유부, 뇌하수체 종양, 유루증을 수반할 수 있는 고프로락틴혈증, 췌장염이나 심한 과트리글리세리드혈증과 관련 경험자, 전조와 같은 국소성 신경학적 증상을 수반하는 두통, 진단되지 않은 질 출혈, C형 간염 직접 작용 항바이러스제 투여, 선천성 또는 후천성 과응고병증, 35세 이상 흡연자, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

