('198601395', '노리스정(클로닉신리시네이트)', '지엘팜텍(주)', '이 약은 근육통, 신경통, 외상후 및 수술후 통증, 두통, 치통, 귀통증의 경증 또는 중등도 통증의 완화에 사용합니다.', '성인은 1회 1~2정(125∼250 mg), 1일 3회 복용합니다.', '소화성궤양 환자, 약물에 기인하여 위·십이지장에 동요 발현, 이 약에 과민증 환자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 억제제 포함)에 천식, 두드러기 또는 알레르기 반응 경험자, 관상동맥 우회로술(CABG) 전후에 발생하는 통증의 치료 환자, 임부 또는 임신하고 있을 가능성이 있는 여성, 심한 간장애, 심한 신장애, 심한 심부전, 크론병 또는 궤양성 대장염과 같은 염증성 장질환 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 소화성궤양의 경험자, 소아 및 고령자, 고혈압, 체액저류 또는 심부전, 기관지천식 환자, 간장애, 신장애 환자 또는 경험자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200901146', '뉴클로정(클로닉신리시네이트)', '한솔신약(주)', '이 약은 근육통, 신경통, 외상후 및 수술후 통증, 두통, 치통, 귀통증의 경증 또는 중등도 통증의 완화에 사용합니다.', '성인은 1회 1~2정(125∼250 mg), 1일 3회 복용합니다.', '소화성궤양 환자, 약물에 기인하여 위·십이지장에 동요 발현, 이 약에 과민증 환자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 억제제 포함)에 천식, 두드러기 또는 알레르기 반응 경험자, 관상동맥 우회로술(CABG) 전후에 발생하는 통증의 치료 환자, 임부 또는 임신하고 있을 가능성이 있는 여성, 심한 간장애, 심한 신장애, 심한 심부전, 크론병 또는 궤양성 대장염과 같은 염증성 장질환 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 소화성궤양의 경험자, 소아 및 고령자, 고혈압, 체액저류 또는 심부전, 기관지천식 환자, 간장애, 신장애 환자 또는 경험자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199401319', '나로펜정(나프록센나트륨)', '오스틴제약(주)', '이 약은 류마티양 관절염, 골관절염(퇴행성 관절질환), 강직성 척추염, 건염(힘줄염), 급성통풍, 월경곤란증과 활액(윤활)낭염, 골격근장애(염좌(삠), 좌상(타박상), 외상(상처), 요천통(허리통증)), 수술후 동통(통증), 편두통, 발치(이를 뽑음)후 통증에 사용합니다.', '류마티양 관절염, 골관절염, 강직성 척추염에 성인은 1회 1~2정(275~550 mg), 1일 2회(12시간마다), 급성통풍에는 초회량(처음 복용량)으로 3정(825 mg) 복용하고 발작이 없어질때까지 8시간 간격으로 1정(275 mg)을 복용, 골격근장애, 수술후 동통(통증), 발치(이를 뽑음)후 동통(통증), 월경곤란증, 건염(힘줄염), 활액(윤활)낭염에는 초회량(처음 복용량)으로 2정(550 mg)을 복용한 후 6~8시간간격으로 1정(275 mg)씩 복용하고 1일 총용량이 5정(1,375 mg)을 초과하지 않도록 합니다. 편두통에는 초회량(처음 복용량)으로 3정(825 mg)을 복용하고 필요하면 1일 1~2정(275~550 mg)을 더 복용할 수 있으며 초회량(처음 복용량)의 복용 30분 후에 복용합니다.

1일 총용량이 5정(1,375 mg)을 초과하지 않도록 합니다.', '매일 세 잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할  때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.

이 약 복용시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다. 이 약에 과민증 환자, 소화성궤양, 심한 혈액이상, 심한 간장애, 심한 심기능부전, 심한 신장애, 심한 고혈압, 아스피린 등 비스테로이드성 소염진통제에 과민증 환자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 저해제 포함)에 의하여 천식, 비염(코염), 코의 용종, 두드러기, 알레르기 반응 또는 경험자, 관상동맥(심장동맥) 우회로술 전후에 발생하는 통증의 치료 및 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자, 임부, 수유부, 2세 이하의 영아는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 임부 및 임신하고 있을 가능성이 있는 부인, 소아, 고령자, 소화성궤양 경험자, 혈액이상 경험자, 출혈경향이 있는 환자, 간장애 또는 경험자, 신장애 또는 경험자, 심기능장애, 고혈압, 기관지천식, 전신성홍반성루푸스 및 혼합결합조직질환 환자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200500806', '나프노펜정(나프록센나트륨)', '(주)일화', '이 약은 류마티양 관절염, 골관절염(퇴행성 관절질환), 강직성 척추염, 건염(힘줄염), 급성통풍, 월경곤란증과 활액(윤활)낭염, 골격근장애(삠, 타박상, 상처, 허리통증), 수술 후 통증, 편두통, 발치 후 통증에 사용합니다.', '류마티양 관절염, 골관절염, 강직성 척추염에 성인은 1회 1~2정(275~550 mg)씩, 1일 2회 12시간마다 복용합니다.

급성통풍에 성인은 처음 복용량으로 3정(825 mg)을 복용하고, 발작이 없어질 때까지 8시간 간격으로 1정(275 mg)을 복용합니다.

골격근장애, 수술후 통증, 발치 후 통증, 월경곤란증, 힘줄염, 활액(윤활)낭염에 성인은 처음 복용량으로 2정(550 mg)을 복용하고 6~8시간 간격으로 1정(275 mg)씩 투여합니다. 1일 총용량은 5정(1,375 mg)을 초과하지 않도록 합니다.

편두통에 성인은 처음 복용량으로 3정(825 mg)을 복용합니다. 필요하면 1일 1~2정(275~550 mg)을 더 복용할 수 있으며 처음 복용량의 복용 30분 후에 복용합니다. 1일 총용량은 5정(1,375 mg)을 초과하지 않도록 합니다.

연령, 증상에 따라 적절히 증감할 수 있습니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 위장출혈을 일으킬 수 있습니다.

이 약 복용 시 치명적일 수 있는 중대한 심혈관계 혈전 반응, 심근경색증, 뇌졸중의 위험이 증가하며, 위장관 출혈, 궤양 및 천공 등 심각한 위장관계 이상반응이 나타날 수 있습니다. 이 약에 과민증, 소화성궤양, 심한 혈액이상, 심한 간장애, 심한 심기능부전, 심한 신장애, 심한 고혈압, 아스피린 등 비스테로이드성 소염진통제에 과민증 환자, 아스피린이나 다른 비스테로이드성 소염진통제(COX-2 저해제 포함)에 의하여 천식, 비염(코염), 코의 용종, 두드러기, 알레르기 반응 또는 경험자, 관상동맥(심장동맥) 우회로술 전후에 발생하는 통증 치료, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 2세 이하의 영아(젖먹이)는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 임신하고 있을 가능성이 있는 여성, 소아, 소화성궤양 경험자, 혈액이상 경험자, 출혈경향이 있는 환자, 간장애 또는 경험자, 신장애 또는 경험자, 신혈류량 저하, 심기능 장애, 고혈압, 기관지천식, 전신성홍반성루푸스 및 혼합결합조직질환 환자, 고령자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('202500808', '세다큐업노즈연질캡슐', '경남제약(주)', '이 약은 콧물, 코막힘, 재채기, 인후(목구멍)통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통 등 감기의 여러 증상의 완화에 사용합니다.', '만 8세 이상~만 15세 미만은 1회 1캡슐씩, 만 15세 이상 및 성인은 1회 2캡슐씩, 1일 3회 식후 30분에 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.

매우 드물게 치명적일 수 있는 급성전신발진고름물집증, 피부점막안증후군(스티븐스-존슨증후군), 독성표피괴사용해(리엘증후군)와 같은 중대한 피부반응이 보고되었고 이 약 복용 후 피부발진 또는 다른 과민반응의 징후가 나타나는 경우 즉시 복용을 중단하십시오.

아세트아미노펜으로 일일 최대 용량(4,000 mg)을 초과하여 복용하지 마십시오. 간손상을 일으킬 수 있습니다. 아세트아미노펜을 포함하는 다른 제품과 함께 복용하지 마십시오.

급성전신발진고름물집증과 같은 중증 피부 이상반응이 나타나는 경우 복용을 중단하고 의사 또는 약사와 상의하십시오. 이 약에 과민증 환자 및 경험자, 이 약 및 이 약의 구성성분, 다른 해열진통제, 감기약 복용 시 천식 경험자, 만 3개월 미만의 영아, 중증 또는 조절되지 않는 고혈압, 중증 급성 또는 만성 신장질환 및 신부전 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 수두 또는 인플루엔자 경험자 또는 의심되는 영아 및 만 15세 미만의 어린이, 만 2세 미만의 소아, 허혈성 대장염의 증상(급격한 복통(배아픔), 직장 출혈 등), 알레르기 체질, 알레르기 반응(발열, 발진, 관절통, 천식, 가려움증 등) 경험자, 간장질환, 신장질환, 심장질환, 갑상선질환, 당뇨병, 고혈압, 위십이지장궤양, 녹내장(눈의 통증, 눈이 침침함 등), 배뇨곤란, 고령자, 몸이 약한 사람, 고열, 속쓰림, 위부불쾌감, 위통과 같은 위장문제, 궤양, 출혈문제, 임부 또는 임신하고 있을 가능성이 있는 여성, 수유부, 흡연, 천식, 만성 기관지염, 폐기종, 과도한 가래가 동반되는 기침, 1주 이상 지속 또는 재발되는 기침, 만성 기침, 발열·발진이나 지속적인 두통이 동반되는 기침 환자는 의사 또는 약사와 상의하십시오.

5~6회 복용하여도 증상이 좋아지지 않을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.

정해진 용법과 용량을 잘 지키십시오.

어린이에게 투여할 경우 보호자의 지도 감독 하에 투여하십시오.

복용 후 졸음이 나타날 수 있으므로 운전 및 기계조작 시 주의하십시오.', '어린이의 손이 닿지 않는 곳에 보관하십시오.

