('202500586', '세다큐업코프연질캡슐', '경남제약(주)', '이 약은 콧물, 코막힘, 재채기, 인후(목구멍)통, 기침, 가래, 오한(춥고 떨리는 증상), 발열, 두통, 관절통, 근육통 등 감기의 여러 증상의 완화에 사용합니다.', '만 8세 이상~만 15세 미만은 1회 1캡슐씩, 만 15세 이상 및 성인은 1회 2캡슐씩, 1일 3회 식후 30분에 복용합니다.', '매일 세잔 이상 정기적 음주자가 이 약 또는 다른 해열진통제를 복용할 때는 의사 또는 약사와 상의하십시오. 간손상을 일으킬 수 있습니다.

