('200402786', '광동동의한방고카타플라스마', '광동제약(주)', '이 약은 삠, 타박상, 근육통, 골절통, 관절통, 요통, 어깨결림, 동창(언 상처)의 진통·소염(항염)에 사용합니다.', '1일 1~2회, 1회 1매씩 환부(질환 부위)에 붙입니다.', '30개월 이하의 유아, 습진, 옻 등에 의한 피부염, 상처부위에는 이 약을 사용하지 마십시오.

