('201802148', '광동만수고골드플라스타', '광동제약(주)', '이 약은 삠, 타박상, 근육통, 관절통, 골절통, 요통, 어깨결림, 동창(언 상처)의 진통ㆍ소염(항염)에 사용합니다.', '성인은 1일 1~2회 질환 부위에 붙입니다.', '30개월 이하의 유아, 습진, 옻 등에 의한 피부염, 상처 부위에 이 약을 사용하지 마십시오.

이 약을 사용하기 전에 약이나 화장품 등에 의한 알레르기 증상(발진·발적, 가려움, 옻 등에 의한 피부염) 경험자, 알레르기 체질, 습윤(습기 참)이나 미란(짓무름)이 심한 환자, 소아, 임부 또는 임신하고 있을 가능성이 있는 여성은 의사 또는 약사와 상의하십시오.

