('200203626', '구미포비돈요오드액', '구미제약(주)', '이 약은 찢긴 상처, 화상, 창상(상처), 욕창의 살균소독, 궤양, 농양(고름집)의 살균소독, 감염피부면의 소독, 수술 부위의 살균소독, 주사 및 카테터부위의 소독에 사용합니다.', '1일 수회(여러 차례) 환부(질환 부위)에 적당량을 바릅니다.', '이 약에 과민증 환자, 갑상선 기능 이상(특히 결절성 갑상선종, 지방병성 갑상선종, 하시모토갑상선염 등), 신부전, 신생아 및 6개월 미만의 영아, 포진상 피부염, 방사성요오드 치료 전후 환자는 이 약을 사용하지 마십시오.이 약을 사용하기 전에 중증의 환자(화상 환자 등), 갑상선질환, 신부전 경험자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부는 의사 또는 약사와 상의하십시오.안과용 및 내복용으로 사용하지 마십시오.눈에 들어가지 않도록 주의하고, 만일 눈에 들어갔을 경우 즉시 깨끗한 물로 씻어내십시오.다른 제제와 혼합해서 사용하지 마십시오.환부를 깨끗이 씻고 소독하십시오.중증의 창상에 사용하는 경우의 희석액으로는 주사용 증류수 또는 멸균정제수를 사용하고, 수도물이나 정제수를 사용하지 마십시오.비누류는 이 약의 살균작용을 약화시키므로 충분히 씻어 제거한 후 사용하십시오.', '빛을 피해 실온에서 보관하십시오.'),
('200102905', '구주로라타딘정10밀리그람(수출명:로히스타정)', '구주제약(주)', '이 약은 알레르기성 비염(재채기, 코막힘, 가려움, 눈의 작열감), 만성 특발성(원인 불명의) 두드러기에 사용합니다.', '성인 및 12세 이상의 소아는 1일 1회 1정(10 mg) 복용합니다.6~12세 미만의 소아는 체중이 30 kg이상인 경우 1일 1회 1정(10 mg), 30 kg이하인 경우 1일 1회 1/2정(5 mg) 복용합니다.연령, 증상에 따라 적절히 증감합니다.', '이 약에 과민증 환자, 만 6세 미만의 소아, 임부 및 수유부,갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 간장애, 신부전 환자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('201802109', '그린쿨인후스프레이액(포비돈요오드)', '(주)그린제약', '이 약은 구강내 살균소독, 인두염, 후두염, 구내염, 발치후 및 구내수술후 살균소독, 구취증에 사용합니다.', '1일 수회 적당량을 분사도포합니다.', '이 약에 과민증 환자, 갑상선기능 이상 환자, 6세 미만의 소아, 방사성요오드 치료 중 및 치료 전후에는 이 약을 사용하지 마십시오.

이 약을 사용하기 전에 입안이 심하게 헐은 환자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 프로필렌글리콜 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.

구강용으로만 사용하십시오.

발치(이를 뽑음) 후 등 구강 창상(상처)의 경우 혈액이 응고하여 출혈이 멎기 전에는 격렬한 양치는 피하십시오.

증상이 개선되지 않거나 악화되는 경우 의사와 상의하십시오.

섬광촬영술을 이용한 갑상선진단에 영향을 줄 수 있습니다. 이 약의 투여와 섬광도 조사는 4주 이상의 간격을 두십시오.

소독용으로 이 약을 과량 사용 시 요오드 독성이 일어날 수 있습니다.

의복 등에 묻은 경우 바로 세척하면 물로 쉽게 씻겨집니다.

실수로 과량 삼켰거나 눈에 들어간 경우 즉시 조치를 취하십시오.

장신구(특히 은을 포함한 제품)에 닿지 않도록 하십시오.

