('200501200', '뉴유스킨에이크림', '(주)보령', '이 약은 살갗이 튼 곳, 추위로 인해 살갗이 거칠어지고 터져서 아픈 곳, 동상에 사용합니다.', '적량을 환부에 바릅니다.손, 발, 팔꿈치, 무릎, 발뒤꿈치 등의 각질화된 부위는 목욕 후나 취침 전에 충분히 문질러 바른 후 장갑이나 양말을 사용하면 효과적입니다.', '30개월 이하의 유아는 이 약을 사용하지 마십시오.이 약을 사용하기 전에 소아, 약 또는 화장품에 과민증 환자, 알레르기 체질, 습윤(습기 참)이나 미란(짓무름)이 심한 환자는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.눈에 들어가지 않도록 주의하고, 만일 눈에 들어간 경우에는 즉시 물 또는 미지근한 물로 씻어내십시오.얼굴 등에 사용할 경우에는 일단 소량을 피부의 부드러운 부분에 적용해 본 후에 사용하십시오.이 약은 외용으로만 사용하고 내복하지 마십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('202004224', '다산알벤다졸정400밀리그램', '(주)다산제약', '이 약은 회충, 요충, 십이지장충, 편충, 아메리카 구충, 분선충의 감염 및 이들 혼합감염의 치료에 사용합니다.', '성인 및 24개월 이상의 소아는 요충에 감염된 경우 1일 1회, 1정(400 mg) 복용합니다. 박멸을 위하여 7일 뒤, 한번만 더 1정(400 mg)을 복용합니다.

회충, 십이지장충, 편충, 아메리카구충에 감염된 경우 1정(400 mg)을 단회(1회) 복용합니다.

분선충의 다른 기생충(조충)과 중증(심한증상) 혼합 감염 시 1일 1회 1정(400 mg)씩, 3일간 복용합니다.

삼키기 어려울 경우 씹거나 소량의 물로 복용할 수 있으며 식사를 중단하거나 하제를 쓰는 등의 특별한 과정은 필요하지 않습니다.

치료 3주 후 검사를 하여 치료되지 않았으면 경우에 따라 2차 투여를 실시할 수 있습니다.', '이 약은 체내에서 페닐알라닌으로 대사되는 아스파탐이 함유되어 페닐알라닌의 섭취를 규제할 필요가 있는 페닐케톤뇨증 환자는 복용하지 마십시오. 이 약에 과민증 환자, 임부 및 임신하고 있을 가능성이 있는 여성 및 수유부, 2세 미만의 소아, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 간장애, 신장애 환자, 황색5호에 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('202500070', '다이어스탑캡슐(로페라미드염산염)', '(주)씨엠지제약', '이 약은 급성설사, 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다.
만성설사인 경우, 초회량은 2캡슐(4 mg)을 복용하고, 설사가 치료될 때까지 묽은 변이 있을 때마다 1캡슐(2 mg)을 복용합니다. 그 이후에는 환자 개별적으로 필요에 맞도록 용량을 감소시킵니다. 1일 최적투여량이 결정되면 이를 1일 1회 또는 1일 2회로 나누어 복용합니다. 보통 유지용량은 1일 1~3캡슐(2~6 mg)이며, 1일 최대용량은 8캡슐(16 mg)입니다.

9~12세의 소아는 급성설사에 1캡슐(2 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 최대용량은 3캡슐(6 mg)입니다.

연령, 증상에 따라 적절히 증감할 수 있습니다.', '24세 미만의 영아, 소아(만성설사인 경우), 혈변 및 고열이 있는 세균성 설사, 급성 궤양성 대장염, 광범위 항생물질 투여와 관련된 위막성 대장염, 장폐색증, 거대결장증, 중독성거대결장증 등을 포함하는 중요한 후유증 위험의 가능성 때문에 연동억제를 피해야 하는 환자, 이 약에 과민증 경험자, 출혈성 대장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 간장애, AIDS 환자, 임부, 수유부, 24개월 이상 7세 이하의 영·유아, 고령자는 의사 또는 약사와 상의하십시오.

급성 설사의 경우 48시간 이내, 만성 설사의 경우 10일 이내 증상의 개선이 없을 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.

체액 및 전해질 손실이 나타날 수 있으므로 적합한 수액 및 전해질을 보충해 주도록 합니다.

복용 후에 피로, 어지러움, 졸음이 나타날 수 있으므로 운전 또는 기계조작 시 주의하십시오.', '실온에서 보관하십시오.'),
