외용으로만 사용하십시오.

5~6일간 사용하여도 증상의 개선이 없을 경우 사용을 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('201507025', '두두엔액', '(주)퍼슨', '이 약은 습진, 피부염, 땀띠, 가려움, 벌레물린데, 두드러기에 사용합니다.', '1일 수회(여러 차례) 환부(질환 부위)에 적당량을 바릅니다.', '이 약에 과민증 환자, 30개월 이하의 유아, 피부감염증(피부결핵, 매독, 칸디다증, 백선, 대상포진, 단순포진, 수두, 종두증, 옴, 사면발이), 막 천공이 있는 습진성 외이도염, 궤양(베체트병 제외), 제2도 심재성 이상의 화상 및 동상, 입주위피부염, 보통여드름, 주사 환자는 이 약을 사용하지 마십시오.피부 감염을 수반하는 습진, 상처부위, 민감한 피부에 사용하지 마십시오.이 약을 사용하기 전에 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 소아, 고령자, 알레르기 체질, 습윤(습기 참)이나 짓무름, 염증이 심한 환자는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.이 약은 외용으로만 사용하고 내복 또는 흡입하지 마십시오.눈 또는 눈 주위, 점막 등에는 사용하지 않아야 하며 이 약이 눈에 들어가지 않도록 주의하고, 만일 눈에 들어간 경우 즉시 물로 씻어내십시오.약액이 묻은 손이 눈 등 점막에 닿으면 자극이 있으므로 손에 묻은 약액은 잘 씻어내십시오.의사의 감독 없이 밀봉붕대법을 사용하지 마십시오.기저귀 등은 밀봉붕대법과 같은 작용을 나타낼 수 있으므로 주의하십시오.화장이나 면도 후 등 치료 이외의 목적으로 사용하지 마십시오.사용 전에 잘 흔들어 사용하십시오.염색한 머리에 사용하면 탈색될 수 있으므로 주의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.화기 근처에 두지 마십시오.'),
('201606648', '두피나액', '일양약품(주)', '이 약은 습진, 피부염, 땀띠, 가려움, 벌레물린데, 두드러기에 사용합니다.', '1일 수회(여러 차례) 환부(질환 부위)에 적당량을 바릅니다.', '이 약에 과민증 환자, 30개월 이하의 유아, 피부감염증(피부결핵, 매독, 칸디다증, 백선, 대상포진, 단순포진, 수두, 종두증, 옴, 사면발이), 막 천공이 있는 습진성 외이도염, 궤양(베체트병 제외), 제2도 심재성 이상의 화상 및 동상, 입주위피부염, 보통여드름, 주사 환자는 이 약을 사용하지 마십시오.피부 감염을 수반하는 습진, 상처부위, 민감한 피부에 사용하지 마십시오.이 약을 사용하기 전에 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 소아, 고령자, 알레르기 체질, 습윤(습기 참)이나 짓무름, 염증이 심한 환자는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.이 약은 외용으로만 사용하고 내복 또는 흡입하지 마십시오.눈 또는 눈 주위, 점막 등에는 사용하지 않아야 하며 이 약이 눈에 들어가지 않도록 주의하고, 만일 눈에 들어간 경우 즉시 물로 씻어내십시오.약액이 묻은 손이 눈 등 점막에 닿으면 자극이 있으므로 손에 묻은 약액은 잘 씻어내십시오.의사의 감독 없이 밀봉붕대법을 사용하지 마십시오.기저귀 등은 밀봉붕대법과 같은 작용을 나타낼 수 있으므로 주의하십시오.화장이나 면도 후 등 치료 이외의 목적으로 사용하지 마십시오.사용 전에 잘 흔들어 사용하십시오.염색한 머리에 사용하면 탈색될 수 있으므로 주의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.화기 근처에 두지 마십시오.'),
('201102036', '둥근머리버물리겔', '현대약품(주)', '이 약은 습진, 피부염, 땀띠, 옻 등에 의한 피부염, 가려움, 동창, 벌레물린데, 두드러기에 사용합니다.', '1일 수회(여러 차례) 환부(질환 부위)에 적당량을 바릅니다.', '30개월 이하의 유아, 눈 또는 눈 주위, 점막, 습진, 상처 부위, 민감한 피부에는 이 약을 사용하지 마십시오. 특히, 벗겨진 피부 표면 또는 물집이 있는 부위에 다량을 사용하지 마십시오.

이 약을 사용하기 전에 약이나 화장품 등에 의한 알레르기 증상(예: 발진·발적(충혈되어 붉어짐), 가려움, 옻 등에 의한 피부염 등)경험자, 알레르기 체질, 습윤(습기 참)이나 미란(짓무름)이 심한 사람, 소아, 순환기 장애 또는 당뇨병 환자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부는 의사 또는 약사와 상의하십시오.

정해진 용법과 용량을 잘 지키십시오.

어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.

이 약은 외용으로만 사용하고 내복 또는 흡입하지 마십시오.

눈에 들어가지 않도록 주의하고, 만일 눈에 들어간 경우 즉시 물로 씻어 내십시오.

사용 전에 잘 흔들어 사용하십시오(외용액제에 한함).

많은 양이 흡수될 경우 중독증상이 나타날 수 있으므로 넓은 표면에 대한 장기간의 사용은 피하십시오.

5~6일간 사용하여도 증상의 개선이 없을 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.

불 근처에 두지 마십시오(인화성 외용액제에 한함).

사용기간이 지난 제품은 사용하지 마십시오.'),
('201309386', '디맥정(농축콜레칼시페롤과립)', '(주)다림바이오텍', '이 약은 골다공증 치료 보조와 흡수장애가 없는 건강한 사람에서 비타민 D 결핍질환 위험으로부터의 예방 및 구루병의 예방에 사용합니다.', '골다공증 치료 보조에 1회 1정(1,000 IU)씩 1일 1회 복용합니다.건강한 사람에서 비타민 D 결핍질환 위험으로부터의 예방 및 구루병 예방에 따른 질환에 이 약으로서 1회 1/2정씩(500 IU) 1일 1회 복용합니다.성인은 충분한 양의 물과 함께 복용합니다.정제를 삼키기 어려운 유아는 숟가락에 정제를 놓고 물에 붕해시킨 후 가능한 식사와 함께 복용합니다.음식에 넣을 때는 음식을 끓인 이후 넣어주고, 비타민D가 많은 식품인 경우 용량조절이 필요할 수 있습니다.', '이 약에 과민증 환자, 고칼슘혈증, 고칼슘뇨증, 신장결석 환자, 3개월 미만의 영아, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 1세 미만의 영아, 햇빛을 많이 보고 정상적인 식사를 하는 어린이, 신장결석 경험자, 유육종증, 움직임이 제한적인 환자(석고깁스), 거짓부갑상선기능저하증, 신장애 환자, 임부 및 수유부는 의사 또는 약사와 상의하십시오.1일 500 IU 이상 복용하는 경우 혈액 및 뇨중 칼슘 수치와 신장기능을 주기적으로 모니터링하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199802009', '러지텍정(세티리진염산염)', '하이플생명과학(주)', '이 약은 계절성 및 다년성 알레르기성 비염, 알레르기성 결막염, 만성 특발성 두드러기, 피부가려움증과 하이드로코티손 외용제와 병용에 의한 습진, 피부염에 사용합니다.', '성인 및 6세 이상의 소아는 1회 1정(10 mg)씩, 1일 1회 취침 전에 복용합니다.

이상반응에 민감한 환자는 1/2정(5 mg)씩, 아침, 저녁에 분할 복용합니다.

연령, 증상에 따라 적절히 증감합니다.

신장애 환자의 투여 간격은 환자의 신기능에 따라 조절되어야 하고, 신장애를 가진 소아 환자는 환자의 신 청소율과 체중을 고려하여 개별적으로 용량을 조절해야 하므로 자세한 사항은 허가사항을 참고하십시오.', '이 약 및 히드록시진 또는 피페라진 유도체에 과민증 또는 경험자, 신부전 환자(크레아티닌 청소율 

이 약을 복용하기 전에 신장장애, 간장애 환자, 노인, 간질 환자 및 발작 위험성이 있는 환자, 소변고임의 선행요인(척수 병변, 전립선 비대증)이 있는 환자, 임부, 수유부는 의사 또는 약사와 상의하십시오.

알레르기항원피내반응검사를 실시하기 3~5일 전에는 이 약을 복용하지 않는 것이 바람직합니다.', '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199901519', '레피즈캡슐(니푸록사지드)', '삼진제약(주)', '이 약은 급성 세균성 설사에 사용합니다.', '성인은 1회 1캡슐(200 mg)씩, 1일 4회 복용합니다.

3일 이상 복용하지 않습니다.

복용 기간 동안 수분을 공급하고 설사의 심각도, 환자의 나이와 상태에 따라 수분의 정도와 공급방법을 조절합니다.', '심하고 지속적인 설사, 구토 혹은 먹는 것을 거부하는 경우에는 정맥 수분 보충을 고려해야 합니다. 이 약에 과민증 환자, 만 18세 미만의 소아 및 청소년, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자, 임부, 효과적인 피임법을 사용하지 않는 가임 여성, 수유부는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 황색5호에 과민증 환자 또는 알레르기 반응 경험자는 의사 또는 약사와 상의하십시오.

치료 후 2일이 지난 후에도 설사가 지속되는 경우 경구 또는 정맥 수분 보충을 고려하거나 의사 또는 약사와 상의하십시오.

설사로 인한 전해물 손실을 보상하기 위해 설탕이나 염분이 풍부한 음료로 수분을 보충하십시오.(성인의 경우 평균 물 2 L정도)', '습기와 빛을 피해 실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199702005', '렉크린액(인산나트륨에네마)', '하이플생명과학(주)', '이 약은 변비, 외과수술시, X-ray조사 및 내시경 검사시의 장세척에 사용합니다.', '성인은 1일 1회 1 병(118 mL), 3세 이상의 소아는 1일 1회 1/2 병(59 mL)을 좌측으로 누운상태나 슬흉위(무릎가슴자세)에서 사용합니다.', '의사의 지시없이 신질환 또는 나트륨제한 식이요법을 하고 있는 경우 이 약을 사용하지 마십시오. 이 약에 과민증 환자, 3세 미만의 소아, 선천성 거대결장증, 울혈성 심부전, 심한 신장기능장애, 위장관 폐쇄, 장폐색, 천공, 항문폐쇄증 환자는 이 약을 사용하지 마십시오.이 약을 사용하기 전에 신장기능장애 환자, 배변 습관의 갑작스런 변화가 2주이상 지속된 사람, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 3∼12세 어린이, 고령자, 거대결장증이 있는 어린이는 의사 또는 약사와 상의하십시오.이 약은 의사의 지시 없이 1주일 이상 사용하지 마십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200001184', '로다인정(로라타딘)', '동성제약(주)', '이 약은 알레르기성 비염(재채기, 코막힘, 가려움, 눈의 작열감), 만성 특발성(원인 불명의) 두드러기에 사용합니다.', '성인 및 12세 이상의 소아는 1일 1회 1정(10 mg) 복용합니다.6~12세 미만의 소아는 체중이 30 kg이상인 경우 1일 1회 1정(10 mg), 30 kg이하인 경우 1일 1회 1/2정(5 mg) 복용합니다.연령, 증상에 따라 적절히 증감합니다.', '이 약에 과민증 환자, 만 6세 미만의 소아, 임부 및 수유부,갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 간장애, 신부전 환자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('201507693', '로라딘연질캡슐(로라타딘)', '한솔신약(주)', '이 약은 알레르기성 비염 증상(재채기, 콧물, 가려움, 눈의 작열감)의 일시적인 완화, 만성 특발성 두드러기 증상 완화에 사용합니다.', '성인 및 12세 이상의 소아는 1일 1회 1캡슐(10 mg)을 복용합니다.6~12세 미만의 소아는 체중 30 kg이상인 경우 1일 1회 1캡슐(10 mg)을 복용합니다.', '이 약에 과민증 환자, 6 세 미만의 소아, 임부 및 수유부, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 간장애 또는 신부전 환자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
