사용기간이 지난 제품은 사용하지 마십시오.'),
('202203169', '로타인정(로라타딘)', '엔비케이제약(주)', '이 약은 알레르기성 비염, 만성 특발성 두드러기에 사용합니다.', '성인 및 12세 이상의 소아는 1회 1정씩, 1일 1회 복용합니다.

