연령, 증상에 따라 적절히 증감할 수 있습니다.', '이 약에 과민증 환자, 6세 미만의 소아, 임부 및 수유부, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

