('197800212', '로파인캡슐(로페라미드염산염)', '태극제약(주)', '이 약은 급성설사와 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다.

성인의 만성설사인 경우, 초회량은 2캡슐(4 mg)을 복용하고, 설사가 치료될 때까지 묽은 변이 있을 때마다 1캡슐(2 mg)을 복용합니다. 그 이후에는 환자 개별적으로 필요에 맞도록 용량을 감소시킵니다. 1일 최적투여량이 결정되면 이를 1일 1회 또는 1일 2회로 나누어 복용합니다. 보통 유지용량은 1일 1~3캡슐(2~6 mg)이며, 1일 최대용량은 8캡슐(16 mg)입니다.

9~12세의 소아는 급성설사에 1캡슐(2 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 최대용량은 3캡슐(6 mg)입니다.

연령, 증상에 따라 적절히 증감할 수 있습니다.

자세한 사항은 허가사항을 참고하십시오.', '이 약에 과민증 경험자, 24개월 미만의 영아, 소아(만성설사인 경우), 혈변 및 고열이 있는 세균성 설사, 급성 궤양성 대장염, 광범위 항생물질 투여와 관련된 위막성 대장염, 장폐색증, 거대결장증, 중독성거대결장증, 출혈성 대장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 간장애, AIDS 환자, 임부 또는 임신할 가능성이 있는 여성 및 수유부, 고령자는 의사 또는 약사와 상의하십시오.

체액 및 전해질 손실이 나타날 수 있으므로 적합한 수액 및 전해질을 보충해 주도록 합니다.

복용 후에 피로, 어지러움, 졸음이 나타날 수 있으므로 운전 또는 기계조작 시 주의하십시오.

만 24개월 이상 7세 이하 영·유아는 반드시 의사 또는 약사의 지시 하에 투여하십시오.

만 24개월 이상 7세 이하 영·유아의 경우 12시간 이상 변을 보지 않으면 투여를 중지하십시오.

급성설사의 경우 48시간 이내, 만성 설사의 경우 10일 이내에 증상의 개선이 없을 경우 투여를 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.'),
('201907189', '로페리캡슐(로페라미드염산염)', '미래바이오제약(주)', '이 약은 급성설사와 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다. 만성설사인 경우, 초회량은 2캡슐(4 mg)을 복용하고, 설사가 치료될 때까지 묽은 변이 있을 때마다 1캡슐(2 mg)을 복용합니다. 그 이후에는 환자 개별적으로 필요에 맞도록 용량을 감소시킵니다. 1일 최적투여량이 결정되면 이를 1일 1회 또는 1일 2회로 나누어 복용합니다. 보통 유지용량은 1일 1~3캡슐(2~6 mg)이며, 1일 최대용량은 8캡슐(16 mg)입니다.

9~12세의 소아는 급성설사에 1캡슐(2 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 최대용량은 3캡슐(6 mg)입니다.

연령, 증상에 따라 적절히 증감할 수 있습니다.', '이 약에 과민증 환자 또는 경험자, 2세 이만의 영아, 혈변 및 고열이 있는 세균성 설사, 급성 궤양성 대장염, 광범위 항생물질 투여와 관련된 위막성 대장염, 장폐색증, 거대결장증, 중독성거대결장증, 출혈성 대장염, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 간장애, AIDS 환자, 임부 또는 임신할 가능성이 있는 여성 및 수유부, 고령자는 의사 또는 약사와 상의하십시오.

체액 및 전해질 손실이 나타날 수 있으므로 적합한 수액 및 전해질을 보충해 주도록 합니다.

복용 후에 피로, 어지러움, 졸음이 나타날 수 있으므로 운전 또는 기계조작 시 주의하십시오.

급성 설사의 경우 48시간 이내, 만성 설사의 경우 10일 이내 증상의 개선이 없을 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.'),
('202402832', '로페스탑캡슐(로페라미드염산염)', '(주)에이프로젠바이오로직스', '이 약은 급성설사, 만성설사에 사용합니다.', '성인은 급성설사인 경우, 2캡슐(4 mg)을 복용하고, 유지량으로는 묽은 변이 있을 때마다 1캡슐(2 mg)씩을 복용합니다. 1일 상용량은 3~4캡슐(6~8 mg)이며, 1일 최대복용량은 8캡슐(16 mg)입니다.
만성설사인 경우, 초회량은 2캡슐(4 mg)을 복용하고, 설사가 치료될 때까지 묽은 변이 있을 때마다 1캡슐(2 mg)을 복용합니다. 그 이후에는 환자 개별적으로 필요에 맞도록 용량을 감소시킵니다. 1일 최적투여량이 결정되면 이를 1일 1회 또는 1일 2회로 나누어 복용합니다. 보통 유지용량은 1일 1~3캡슐(2~6 mg)이며, 1일 최대용량은 8캡슐(16 mg)입니다.

