('199602289', '루마겔(케토프로펜)', '한미약품(주)', '이 약은 퇴행성관절염(골관절염), 어깨관절주위염, 건ㆍ건초염, 건주위염, 상완골상과염(테니스 엘보우 등), 근육통, 외상후의 종창ㆍ동통의 진통ㆍ소염에 사용합니다.', '증상에 따라 적당량을 1일 1~4회 환부에 바르고 잘 스며들도록 가볍게 문지릅니다.', '이 약에 과민증, 광과민증, 아스피린 또는 다른 소염진통제에 의한 천식 경험 환자, 티아프로펜산ㆍ페노피브레이트ㆍ베자피브레이트ㆍ시프로피브레이트ㆍ옥시벤존에 과민증, 임신기간 6개월 이상인 임부, 15세 미만의 소아는 이 약을 사용하지 마십시오.이 약을 사용하기 전에 기관지천식, 임부, 수유부는 의사 또는 약사와 상의하십시오.광과민증이 나타날 수 있으므로, 이 약을 사용 중이거나 사용 후 2주까지는 자외선을 피하십시오.눈 및 점막, 무좀, 백선에는 사용하지 마십시오.손상된 피부 및 점막, 습진 또는 발진 부위에 사용하는 경우 일시적인 자극 및 날카로운 통증을 일으킬 수 있으므로 사용시 주의하십시오.밀봉붕대법을 사용하지 마십시오.1주일 정도 사용하고도 증상개선이 보이지 않을 경우 사용을 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
