('202200851', '리버칼에프연질캡슐350밀리그램(밀크시슬열매건조엑스)', '(주)한국파비스제약', '이 약은 독성간질환, 만성간염, 간경변의 보조치료에 사용합니다.', '1회 1캡슐씩, 1일 1회 복용합니다.', '이 약에 과민증, 심한 담도(쓸개길) 폐쇄, 12세 이하의 소아, 대두유 과민증 또는 알레르기 반응 경험자, 콩 또는 땅콩 과민증 환자는 이 약을 복용하지 마십시오.

