어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('195900034', '신신티눈고(살리실산반창고)(수출명:SINSINCORNPLASTER)', '신신제약(주)', '이 약은 티눈, 못(굳은살), 사마귀에 사용합니다.', '이형지로부터 벗겨 이 약제면을 환부(질환 부위)에 대고 테이프로 고정하고 2~5일마다 교체하여 붙입니다.', '이 약에 과민증 환자, 당뇨병, 혈액순환장애 환자는 이 약을 사용하지 마십시오.

눈 주위, 점막, 감염, 염증, 발적(충혈되어 붉어짐), 자극이 있는 부위, 점, 태어날 때부터 있는 점 또는 사마귀, 털이 있는 사마귀, 생식기 부위의 사마귀에 사용하지 마십시오.

이 약을 사용하기 전에 영아 및 유아, 약 또는 화장품에 과민증 환자, 신부전 환자, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부는 의사 또는 약사와 상의하십시오.

정해진 용법과 용량을 잘 지키십시오.

수회(여러 차례) 사용하여도 증상의 개선이 없을 경우 사용을 즉각 중지하고 의사 또는 약사와 상의하십시오.

화농(곪음)성피부염, 습윤(습기 참), 미란(짓무름)의 경우 이를 미리 치료한 후 이 약을 적용하십시오.

이 약을 붙인 채로 물 속에 들어가는 경우에는 약고가 녹아서 없어질 수 있으므로 주의하십시오.

어린이에게 사용할 경우 보호자의 지도 감독하에 사용하십시오.

이 약은 외용으로만 사용하십시오.

눈, 코, 입 및 다른 점막에 닿지 않도록 주의하여 적용하고, 만일 눈에 들어갔을 경우 충분한 양의 물로 완전히 씻어내십시오.

환부(질환 부위) 이외의 피부에 닿지 않도록 주의하십시오.', '습기와 빛을 피해 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.

화기 근처에 두지 마십시오.'),
('195900043', '아네모정', '삼진제약(주)', '이 약은 위산과다, 속쓰림, 위부불쾌감, 위부팽만감, 체함, 구역, 구토, 위통, 신트림에 사용합니다.', '성인 1회 2정, 1일 3회 식간(식사와 식사때 사이) 및 취침시에 복용합니다.', '투석요법을 받고 있는 환자, 수유부, 만 7세 이하의 어린이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 이 약에 과민증 환자, 알레르기 체질, 알레르기 증상(발진, 충혈되어 붉어짐, 가려움 등) 경험자, 신장장애 환자, 임부 또는 임신하고 있을 가능성이 있는 여성, 나트륨 제한 식이를 하는 사람은 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.', '습기와 빛을 피해 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('197100015', '타치온정50밀리그램(글루타티온(환원형))', '동아제약(주)', '이 약은 약물중독, 자가중독에 사용합니다.', '성인은 1회 1~2정(50~100 mg), 1일 1~3회 복용합니다.

연령, 증상에 따라 적절히 증감합니다.', NULL, '실온에서 보관하십시오.

어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('197400207', '겔포스현탁액(인산알루미늄겔)', '(주)보령', '이 약은 위·십이지장 궤양, 위염, 위산과다(속쓰림, 위통, 구역, 구토)의 제산작용 및 증상의 개선에 사용합니다.', '성인은 1회 1포씩, 1일 3~4회 식간(식사 때와 식사 때 사이) 및 취침 시 복용합니다.

연령 또는 증상에 따라 적절히 증감합니다.', '이 약을 복용하기 전에 신장장애, 변비 환자는 의사 또는 약사와 상의하십시오.', '빛을 피해 실온에서 보관하십시오.'),
('197700189', '일양노이겔현탁액(규산알루민산마그네슘)', '일양약품(주)', '이 약은 위산과다 위ㆍ십이지장염 위염의 제산작용 및 증상의 개선에 사용합니다.', '성인은 1회 1/2포~1포(0.5~1 g) 1일 3~4회 공복시에 복용합니다.연령 또는 증상에 따라 적절히 증감합니다.', '이 약을 복용하기 전에 간장애, 심기능장애, 고마그네슘혈증 환자는 의사 또는 약사와 상의하십시오.', '빛을 피해 실온에서 보관하십시오.'),
('195900045', '자모', '씨에이치디제약주식회사', '이 약은 기침, 가래, 천식에 사용합니다.', '성인은 1회 10 g, 11~14세는 1회 7 g, 8~10세는 1회 5 g, 5~7세는 1회 3 g씩, 1일 3회 식후에 복용합니다.', '이 약에 과민증 환자 또는 경험자, 만 3개월 미만의 영아 및 만 2세 미만의 소아는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 알레르기 체질, 약에 의한 알레르기 증상(발열, 발진, 관절통, 가려움증 등) 경험자, 꼭 필요한 경우의 만 2세 미만의 소아, 임부 또는 임신하고 있을 가능성이 있는 여성, 수유부, 간장질환, 신장질환, 심장질환, 갑상선질환, 당뇨병, 고혈압 등이 있는 사람, 고령자, 몸이 약한 사람 또는 고열이 있는 사람, 흡연, 천식, 만성 기관지염, 폐기종, 과도한 가래가 동반되는 기침, 1주 이상 지속 또는 재발되는 기침, 만성 기침, 발열·발진이나 지속적인 두통이 동반되는 기침이 있는 사람은 의사 또는 약사와 상의하십시오.

5~6회 복용하여도 증상이 좋아지지 않을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.

어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.

