('197800242', '일양노이시린에이정(규산알루민산마그네슘)', '일양약품(주)', '이 약은 위산과다 위ㆍ십이지장염 위염의 제산작용 및 증상의 개선에 사용합니다.', '성인은 1회 1~2정(0.5~1 g), 1일 3~4회 공복시에 복용합니다.연령 또는 증상에 따라 적절히 증감합니다.', '이 약을 복용하기 전에 간장애, 심기능장애, 고마그네슘혈증 환자는 의사 또는 약사와 상의하십시오.', NULL),
('198401161', '세나서트2밀리그람질정', '알보젠코리아(주)', '이 약은 세균성질증에 사용합니다.', '성인은 1회 1정, 1일 1회 질내 깊숙이 삽입합니다.', '이 약에 과민증 환자는 이 약을 사용하지 마십시오.이 약은 질에만 사용하고 내복용으로는 사용하지 마십시오.이 약은 콘돔, 질내피임용격막과 같은 라텍스 또는 고무제품을 약화시킬 수 있으므로 주의하십시오.', '습기와 빛을 피해 서늘한 곳에 보관하십시오.'),
('199100317', '대한염화나트륨액', '대한약품공업(주)', '이 약은 피부, 창상면, 점막의 세정, 습포 및 함수(양치질), 분무흡입제로서 점막세정, 객담배출 촉진, 의료용구의 세정에 사용합니다.', '적당량을 사용합니다.', '이 약을 주사용으로 사용하지 마십시오.', '실온에서 보관하십시오.'),
('199100655', '옵타젠트점안액(포비돈)', '삼일제약(주)', '이 약은 건조한 눈, 하드콘택트렌즈 착용시에 사용합니다.', '1회 1~2방울 1일 4~5회 점안합니다.증상에 따라 적절히 증감합니다.', '치료 중에는 소프트콘택트렌즈의 착용을 피하십시오.점안용으로만 사용하십시오.오염을 방지하기 위해 될 수 있는 한 공동으로 사용하지 마십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('196200034', '삐콤정', '(주)유한양행', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후의 체력 저하 시 비타민 B1, B2, B6, C의 보급에 사용합니다.', '만 8세 이상 및 성인은 1회 1~3정씩, 1일 1회 복용합니다.', '이 약에 과민증 환자, 만 3개월 미만의 젖먹이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.
이 약을 복용하기 전에 만 1세 미만의 젖먹이, 고옥살산뇨증(요중에 과량의 수산염이 배설되는 상태), 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 미숙아, 유아, 통풍, 신장결석, 폴산이 부족한 환자는 의사 또는 약사와 상의하십시오.
정해진 용법과 용량을 잘 지키십시오.
어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.
각종 요검사 시에 혈당의 검출을 방해할 수 있으며, 요를 황색으로 변하게 하여 임상검사치에 영향을 줄 수 있습니다.
1개월 정도 복용하여도 증상의 개선이 없을 경우 복용을 즉각 중지하고 의사 또는 약사와 상의하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('196400046', '게루삼정', '삼남제약(주)', '이 약은 위산과다, 속쓰림, 위부불쾌감, 위부팽만감, 체함, 구역, 구토, 위통, 신트림에 사용합니다.', '만 15세 이상 및 성인은 1회 2정, 만 8세 이상 15세 미만은 1회 1정, 1일 3회 식간(식사때와 식사때 사이) 및 취침시 복용합니다.복용간격은 4시간 이상으로 합니다.', '투석요법을 받고 있는 환자, 만 7세 이하의 어린이는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 신장장애 환자, 나트륨 제한 식이를 하는 사람은 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('196400089', '보화소합원(대환,소환)', '원광제약(주)', '이 약은 식욕감퇴(식욕부진), 위부팽만감, 소화불량, 과식, 체함, 구역, 구토에 사용합니다.', '대환은 1회 1∼2환을 1일 3회 식후에 소량의 물과 함께 복용하십시오.소환은 1회 8∼16환을 1일 3회 식후에 소량의 물과 함께 복용하십시오.', '만 7세 이하의 소아는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 혈압이 높은 환자, 고령자, 심장 또는 신장(콩팥)에 장애가 있는 환자, 부종(부기)이 있는 사람은 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.어린이에게 투여할 경우 보호자의 지도 감독하에 투여하십시오.', '습기와 빛을 피해 건냉암소에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('196500051', '지엘타이밍정(카페인무수물)', '지엘팜텍(주)', '이 약은 졸음에 사용합니다.', '성인은 1회 2~6정(100~300 mg)씩, 1일 1~3회 복용합니다.연령, 증상에 따라 적절히 증감할 수 있습니다.', '갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.이 약을 복용하기 전에 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 고령자, 위궤양 환자 또는 경험자, 심질환, 녹내장 환자는 의사 또는 약사와 상의하십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199303012', '엔클비액(염화나트륨)', '한림제약(주)', '이 약은 비점막 건조 증상의 완화에 사용합니다.', '성인은 증상에 따라 필요시 각 비강에 2방울씩 점적합니다.

연령, 증상에 따라 적절히 증감합니다.', '이 약 또는 벤잘코늄염화물에 과민증(발진, 발적, 종창, 자극감 등) 환자는 이 약을 사용하지 마십시오.

