('199400693', '지노콜시럽(구연산부타미레이트)', '동성제약(주)', '이 약은 급성기침, 경련성기침, 흡연성기침, 기관지경 검사 전·후의 기침 억제에 사용합니다.', '성인은 1회 15 mL (22.5 mg), 1일 4회, 12~14세는 1회 15 mL (22.5 mg), 6~11세는 1회 10 mL (15 mg), 3~5세는 1회 5 mL (7.5 mg), 1일 3회 복용합니다.', '이 약에 과민증 환자, 임부는 이 약을 복용하지 마십시오.', '습기를 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('199502669', '제로미아액', '오스템파마주식회사', '이 약은 약물치료, 구강 또는 인후 부근의 방사선 치료, 타액선 감염, 구강 또는 인후감염, 치아 또는 구강수술, 발열, 정서적요인으로 인한 타액분비감소에 사용합니다.', '구강내 습기를 유지하는데 필요한 만큼 또는 의사의 지시에 따라 구강이나 인후에 1~2회 동안 직접 분무합니다.', '이 약에 과민증 환자는 이 약을 사용하지 마십시오.눈에 분무하지 마십시오.', '실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('196600011', '베스타제정', '동아제약(주)', '이 약은 소화불량, 식욕감퇴(식욕부진), 과식, 체함, 소화촉진, 소화불량으로 인한 위부팽만감에 사용합니다.', '성인(만 15세 이상)은 1회 2정씩, 만 11세 이상~만 15세 미만은 1회 1~2정씩, 만 8세 이상~만 11세 미만은 1회 1정씩, 1일 3회 식후에 복용합니다.', '만 7세 이하의 어린이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

