('196600012', '베스타제당의정', '동아제약(주)', '이 약은 소화불량, 식욕감퇴(식욕부진), 과식, 체함, 소화촉진, 소화불량으로 인한 위부팽만감에 사용합니다.', '성인(만 15세 이상)은 1회 2정씩, 만 11세 아상~만 15세 미만은 1회 1~2정씩, 만 8세 이상~만 11세 미만은 1회 1정씩을 1일 3회 식후에 복용합니다.', '만 7세 이하의 어린이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

