('199806424', '포스테리산연고', '동화약품(주)', '이 약은 치질에 사용합니다.', '1일 2회, 가능한 한 배변 후 적량을 환부(질환 부위)에 바릅니다.', '이 약에 과민증 환자는 이 약을 사용하지 마십시오.재발을 방지하기 위하여 염증 및 가려움, 수포, 작열감(화끈감) 등의 증상이 소실되더라도 장기간 계속하여 바르십시오.이 약은 항문 부위에만 사용하고 안과용으로는 사용하지 마십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('200009088', '로와치넥스캡슐', '(주)한국팜비오', '이 약은 신증, 요로결석증의 보조요법에 사용합니다.', '성인은 1회 1캡슐 1일 3~4회 복용합니다.', '임신 초기 3개월 여성은 이 약을 복용하지 마십시오.이 약을 복용하기 전에 이 약에 발진, 발적, 가려움 등 경험자는 의사 또는 약사와 상의하십시오.정해진 용법과 용량을 잘 지키십시오.', '습기와 빛을 피해 실온에서 보관하십시오.어린이의 손이 닿지 않는 곳에 보관하십시오.'),
('197000037', '아로나민골드정', '일동제약(주)', '이 약은 육체피로, 임신ㆍ수유기, 병중ㆍ병후(병을 앓는 동안이나 회복 후)의 체력 저하 시, 노년기(간유, 비타민 D, E 함유시)의 비타민 B1, B2, B6, E, C의 보급과 신경통, 근육통, 관절통(요통, 어깨결림 등) 증상의 완화, 각기, 눈의 피로에 사용합니다.', '성인은 1회 1정씩, 1일 2회 복용합니다.', '이 약에 과민증 환자, 만 3개월 미만의 젖먹이, 갈락토오스 불내성, Lapp 유당분해효소 결핍증 또는 포도당-갈락토오스 흡수장애 등의 유전적인 문제가 있는 환자는 이 약을 복용하지 마십시오.

이 약을 복용하기 전에 고옥살산뇨증(뇨중에 과량의 수산염이 배설되는 상태), 임부 및 임신하고 있을 가능성이 있는 여성, 수유부, 미숙아, 유아, 통풍 또는 신장결석, 폴산이 부족한 환자, 혈전성 소인이 있는 환자, 황색5호에 과민증 환자 또는 경험자는 의사 또는 약사와 상의하십시오.

정해진 용법과 용량을 잘 지키십시오.

각종 요검사 시에 혈당의 검출을 방해할 수 있으며, 요를 황색으로 변하게 하여 임상검사치에 영향을 줄 수 있습니다.', '습기와 빛을 피해 실온에서 보관하십시오.

