('197000040', '대웅우루사연질캡슐', '(주)대웅제약', '이 약은 만성 간질환의 간기능 개선과 간기능 장애에 의한 육체피로, 전신권태 증상의 개선에 사용합니다.', '성인은 1회 1캡슐씩, 1일 3회 복용합니다.', '이 약에 과민증 환자, 심한 담도폐쇄, 전격성 간염, 임부 또는 임신하고 있을 가능성이 있는 여성 및 수유부, 소아, 크론병과 같은 대장 및 소장염, 방사선 비투과성 석회화된 담석, 비기능성 담낭(쓸개), 급성 담낭(쓸개)염, 신질환, 소화성궤양(급성 위ㆍ십이지장 궤양) 환자, 대두유·콩·땅콩 과민증 또는 알레르기 반응 경험자는 이 약을 복용하지 마십시오.

